302:     void allocate_dense_facedata(size_t nfaces, size_t nbfaces, size_t neq, size_t nftl)
303:     {
304:     /*
305:         Both kinds of blocks now share a structure of densely packed core flow
306:         data. This routine allocates the storage for these structures,
307:         attempting to keep related bits of data together on the heap.
308: 
309:         @author: Nick Gibbons
310:     */
311:         auto gmodel = myConfig.gmodel;
312:         size_t nturb = myConfig.turb_model.nturb;
313:         size_t ngtl = myConfig.n_grid_time_levels;
314: 
315:         facedata.all_face_idxs.length = nfaces;
316:         foreach(i; 0 .. nfaces) facedata.all_face_idxs[i] = i;
317: 
318:         facedata.positions.length = nfaces;
319:         facedata.areas.length = nfaces*ngtl;
320:         facedata.grid_velocities.length = nfaces*ngtl;
321:         facedata.normals.length = nfaces;
322:         facedata.tangents1.length = nfaces;
323:         facedata.tangents2.length = nfaces;
324:         facedata.left_interior_only.length = nfaces;
325:         facedata.right_interior_only.length = nfaces;
326:         facedata.stencil_idxs.length = nfaces;
327:         facedata.fluxes.length = nfaces*neq;
328:         facedata.f2c.length = nfaces;
329: 
330:         if (myConfig.interpolation_order>=2) facedata.l2r2_interp_data.length = nfaces;
331:         if (myConfig.interpolation_order==3) facedata.l3r3_interp_data.length = nfaces;
332: 
333:         facedata.flowstates.reserve(nfaces);
334:         foreach (n; 0 .. nfaces) facedata.flowstates ~= FlowState(gmodel, nturb);
335:         facedata.gradients.reserve(nfaces);
336:         foreach (n; 0 .. nfaces) facedata.gradients ~= FlowGradients(myConfig);
337:         facedata.workspaces.reserve(nfaces);
338:         foreach (n; 0 .. nfaces) facedata.workspaces ~= WLSQGradWorkspace();

1297:     void initialize_jacobian(int spatial_order_of_jacobian, double sigma, int iluFill=-1)
1298:     {
1299:         /*
1300:           This method initializes the flow Jacobian matrix attached the FluidBlock object.
1301:           We gather the cell/interface residual stencils for the interior and ghost cells at this point,
1302:           since we need to know the number of expected entries in the Jacobian matrix to pre-size the
1303:           sparse matrix arrays.
1304:          */
1305: 
1306:         size_t nentry = 0;
1307:         GasModel gmodel = cast(GasModel) myConfig.gmodel;
1308:         if (gmodel is null) { gmodel = GlobalConfig.gmodel_master; }
1309:         fs_save = new FlowState(gmodel, myConfig.turb_model.nturb);
1310: 
1311:         // gather the expected number of non-zero entries in the flow Jacobian
1312:         foreach (cell; cells) {
1313:             if (cell.doNotPerturb) {
1314:                 cell.cell_list ~= cell; 
1315:             }
1316:             else {
1317:                 cell.gather_residual_stencil_lists(spatial_order_of_jacobian);
1318:             }
1319:             nentry += cell.cell_list.length;
1320:         }
1321: 
1322:         // we will gather the ghost cell residual stencil lists
1323:         // at this point as well for convenience, we need them
1324:         // when we apply the boundary condition corrections later
1325:         foreach ( bndary; bc ) {
1326:             if (!bndary.ghost_cell_data_available) { continue; }
1327:             if (bndary.type == "exchange_using_mapped_cells" ||
1328:                 bndary.type == "exchange_over_full_face" ||
1329:                 bndary.type == "do_nothing") {
1330:                 continue;
1331:             }
1332:             foreach ( iface, face; bndary.faces) {
1333:                 FluidFVCell ghost_cell, cell;
1334:                 if (bndary.outsigns[iface] == 1) {
1335:                     cell = face.left_cell;
1336:                     ghost_cell = face.right_cell;
1337:                 } else {
1338:                     cell = face.right_cell;
1339:                     ghost_cell = face.left_cell;
1340:                 }
1341:                 ghost_cell.gather_residual_stencil_lists_for_ghost_cells(spatial_order_of_jacobian, cell.cell_cloud);
1342:             }
1343:         }
1344: 
1345:         jacobian_nonzero_pattern(spatial_order_of_jacobian, nentry, cells.length, sigma, iluFill);
1346:     } // end initialize_jacobian()

1348:     void jacobian_nonzero_pattern(int spatial_order_of_jacobian, size_t nentry, size_t ncells, double sigma, int iluFill=-1) {
1349:         /*
1350:           This routine will fill out the sparse matrix with the appropriate non-zero structure
1351:         */
1352: 
1353:         // We first construct a temporary sparse matrix to store the point structure of the system
1354:         // i.e. each nConserved x nConserved block is represented by a single entry
1355:         FlowJacobian ptJac = new FlowJacobian(0.0, myConfig.dimensions, 1, spatial_order_of_jacobian, nentry, ncells);
1356:         ptJac.local.ia[ptJac.ia_idx] = 0; // the first entry will always be filled
1357:         ptJac.ia_idx += 1;
1358:         foreach (pcell; cells) {
1359:             // loop through cells that will have non-zero entries
1360:             foreach(cell; pcell.cell_list) {
1361:                 assert(!cell.is_ghost, "Oops, we expect to not find a ghost cell at this point.");
1362:                 size_t jidx = cell.id; // column index
1363:                 // populate entry with a place holder value
1364:                 ptJac.local.aa[ptJac.aa_idx] = 1.0;
1365:                 // fill out the sparse matrix ready for the next entry in the row
1366:                 ptJac.aa_idx += 1;
1367:                 ptJac.local.ja[ptJac.ja_idx] = jidx;
1368:                 ptJac.ja_idx += 1;
1369:             }
1370:             // prepare the sparse matrix for a new row
1371:             ptJac.local.ia[ptJac.ia_idx] = ptJac.aa_idx;
1372:             ptJac.ia_idx += 1;
1373:         }
1374: 
1375:         // For ILU(p>0) we need to modify the sparsity pattern
1376:         if (iluFill > 0) {
1377: 
1378:             // [TODO] think about making the lev matrix sparse as well KAD 2022-03-31
1379:             // construct a level matrix
1380:             int p = iluFill;
1381:             int n = to!int(ptJac.local.ia.length)-1;
1382:             int[][] lev; // fill levels
1383:             lev.length = n;
1384:             foreach ( i; 0..n) lev[i].length = n;
1385:             // assign initial fill levels
1386:             foreach ( i; 0 .. n ) {
1387:                 foreach ( j; 0 .. n ) {
1388:                     if (ptJac.local[i,j] < 1.0) lev[i][j] = n-1;
1389:                     else lev[i][j] = 0;
1390:                 }
1391:             }
1392: 
1393:             // apply symbolic phase algorithm
1394:             foreach ( i; 1 .. n ) { // Begin from 2nd row
1395:                 foreach ( k; 0 .. i ) {
1396:                     if (lev[i][k] <= p) {
1397:                         foreach ( j ; k+1..n) {
1398:                             lev[i][j] = min(lev[i][j], lev[i][k]+lev[k][j]+1);
1399:                         }
1400:                     }
1401:                 }
1402:             }
1403: 
1404:             // modify the sparse matrix non-zero pattern based on the level matrix
1405:             foreach ( i; 0..n) {
1406:                 foreach ( j; 0..n) {
1407:                     // add new entry
1408:                     if (lev[i][j] <= p) { ptJac.local[i,j] = 1.0; }
1409:                 }
1410:             }
1411:         }
1412: 
1413:         // we now construct the full sparse matrix by replacing each entry with an nConserved x nConserved block
1414:         auto cqi = myConfig.cqi;
1415:         auto nConserved = cqi.n;
1416: 
1417:         size_t n_vtx = (myConfig.grid_motion != GridMotion.none) ? vertices.length : 0;
1418:         flowJacobian = new FlowJacobian(sigma, myConfig.dimensions, nConserved, spatial_order_of_jacobian, ptJac.local.aa.length, ncells, n_vtx);
1419:         flowJacobian.local.ia[flowJacobian.ia_idx] = 0;
1420:         flowJacobian.ia_idx += 1;
1421:         size_t n = ptJac.local.ia.length-1;
1422:         foreach ( rowi; 0 .. n ) { // foreach row in the point sparse matrix
1423:             // loop through nConserved rows
1424:             for (size_t ip = 0; ip < nConserved; ++ip) {
1425:                 foreach (colj; ptJac.local.ja[ptJac.local.ia[rowi] .. ptJac.local.ia[rowi+1]] ) { // foreach non-zero col in the point sparse matrix
1426:                     for (size_t jp = 0; jp < nConserved; ++jp) {
1427:                         size_t jidx = colj*nConserved + jp; // column index
1428:                         // populate entry with a place holder value
1429:                         flowJacobian.local.aa[flowJacobian.aa_idx] = 1.0;
1430:                         // fill out the sparse matrix ready for the next entry in the row
1431:                         flowJacobian.aa_idx += 1;
1432:                         flowJacobian.local.ja[flowJacobian.ja_idx] = jidx;
1433:                         flowJacobian.ja_idx += 1;
1434:                     }
1435:                 }
1436:                 // prepare the sparse matrix for a new row
1437:                 flowJacobian.local.ia[flowJacobian.ia_idx] = flowJacobian.aa_idx;
1438:                 flowJacobian.ia_idx += 1;
1439:             }
1440:         }
