1826:     void allocate_GMRES_workspace(int maxLinearSolverIterations, bool useRealValuedFrechetDerivative)
1827:     {
1828:         size_t nConserved = GlobalConfig.cqi.n;
1829:         int n_species = GlobalConfig.gmodel_master.n_species();
1830:         int n_modes = GlobalConfig.gmodel_master.n_modes();
1831:         maxRate = new ConservedQuantities(nConserved);
1832:         residuals = new ConservedQuantities(nConserved);
1833: 
1834:         size_t m = to!size_t(maxLinearSolverIterations);
1835:         size_t n = nConserved*cells.length;
1836: 
1837:         // add the number of grid degrees of freedom to the total
1838:         // number of variables
1839:         if (myConfig.grid_motion != GridMotion.none) {
1840:             foreach (ref vtx; vertices) {
1841:                 if (vtx.solve_position) { n += myConfig.dimensions; } 
1842:             }
1843: 
1844:             maxVel.length = myConfig.dimensions;
1845:         }
1846: 
1847:         nvars = n;
1848:         // Now allocate arrays and matrices
1849:         R.length = n;
1850:         if (useRealValuedFrechetDerivative) { R0.length = n; }
1851:         dU.length = n; dU[] = 0.0;
1852:         r0.length = n;
1853:         x0.length = n;
1854:         DinvR.length = n;
1855:         rhs.length = n;
1856:         v.length = n;
1857:         w.length = n;
1858:         zed.length = n;
1859:         g0.length = m+1;
