283:     override void init_grid_and_flow_arrays(string gridFileName)
284:     {
285:         grid = new UnstructuredGrid(gridFileName, myConfig.grid_format, myConfig.true_centroids);
286:         if (grid.nvertices != nvertices) {
287:             string msg = format("UnstructuredGrid: incoming grid has %d vertices " ~
288:                                 "but expected %d vertices.", grid.nvertices, nvertices);
289:             throw new FlowSolverException(msg);
290:         }
291:         if (grid.nfaces != nfaces) {
292:             string msg = format("UnstructuredGrid: incoming grid has %d faces " ~
293:                                 "but expected %d faces.", grid.nfaces, nfaces);
294:             throw new FlowSolverException(msg);
295:         }
296:         if (grid.ncells != ncells) {
297:             string msg = format("UnstructuredGrid: incoming grid has %d cells " ~
298:                                 "but expected %d cells.", grid.ncells, ncells);
299:             throw new FlowSolverException(msg);
300:         }
301:         grid.sort_cells_into_bins();
302:         ninteriorfaces = grid.ninteriorfaces;
303: 
304:         // Assemble array storage for finite-volume cells, etc.
305:         bool lsq_workspace_at_vertices = (myConfig.viscous) && (myConfig.spatial_deriv_calc == SpatialDerivCalc.least_squares)
306:             && (myConfig.spatial_deriv_locn == SpatialDerivLocn.vertices);
307:         foreach (i, v; grid.vertices) {
308:             auto new_vtx = new FVVertex(myConfig, lsq_workspace_at_vertices, to!int(i));
309:             new_vtx.pos[0] = v;
310:             vertices ~= new_vtx;
311:         }
312: 
313:         // Allocate densified face and cell data
314:         auto gmodel = myConfig.gmodel;
315:         size_t neq    = myConfig.cqi.n;
316:         size_t nsp    = myConfig.n_species;
317:         size_t nmodes = myConfig.n_modes;
318:         size_t nturb  = myConfig.turb_model.nturb;
319:         size_t nftl   = myConfig.n_flow_time_levels;
320: 
321:         size_t nghost = 0;
322:         foreach (bndry; grid.boundaries) nghost += bndry.face_id_list.length;
323: 
324:         allocate_dense_celldata(ncells, nghost, neq, nftl);
325:         allocate_dense_facedata(nfaces, nghost, neq, nftl); // nghost==nbfaces for unstructured
326: 
327:         // We have some unstructured specific stuff that also needs to be allocated
328:         celldata.face_distances.length = ncells;
329:         celldata.lsqws.length = ncells + nghost;
330:         celldata.cell_cloud_indices.length = ncells;
331:         celldata.c2v.length = ncells;
332:         celldata.lsqgradients.reserve(ncells + nghost);
333:         foreach (i; 0 .. ncells + nghost) celldata.lsqgradients ~= LSQInterpGradients(nsp, nmodes, nturb); // TODO: skip if not needed
334:         // TODO: for now this is only needed for the adjoint solver and/or the check-jacobian tool - we can think about dropping this for the flow solver. KAD 2024-08-28
335:         celldata.saved_lsqgradients.reserve(ncells + nghost);
336:         foreach (n; 0 .. ncells+nghost) celldata.saved_lsqgradients ~= LSQInterpGradients(myConfig.n_species, myConfig.n_modes, myConfig.turb_model.nturb);
337: 
338:         facedata.dL.length = nfaces;
339:         facedata.dR.length = nfaces;
340: 
341:         foreach (i, f; grid.faces) {
342:             auto new_face = new FVInterface(myConfig, IndexDirection.none, &facedata, to!int(i));
343:             faces ~= new_face;
344:         }
345: 
346:         cells.reserve(ncells + nghost);
347:         foreach (i, c; grid.cells) {
348:             // Note that the cell id and the index in the cells array are the same.
349:             // We will reply upon this connection in other parts of the flow code.
350:             auto new_cell = new FluidFVCell(myConfig, &celldata, to!int(i));
351:             new_cell.contains_flow_data = true;
352:             new_cell.is_interior_to_domain = true;
353:             cells ~= new_cell;
354:         }
355:         // Bind the interfaces, vertices and cells together,
356:         // using the indices stored in the unstructured grid.
357:         foreach (i, f; faces) {
358:             foreach (j; grid.faces[i].vtx_id_list) {
359:                 f.vtx ~= vertices[j];
360:             }
361:         }
362:         celldata.outsigns.length=cells.length;
363:         celldata.c2f.length = cells.length;
364:         foreach (i, c; cells) {
365:             foreach (j; grid.cells[i].vtx_id_list) {
366:                 c.vtx ~= vertices[j];
367:                 celldata.c2v[i] ~= j;
368:             }
369:             auto nf = grid.cells[i].face_id_list.length;
370:             if (nf != grid.cells[i].outsign_list.length) {
371:                 string msg = format("Mismatch in face_id_list, outsign_list lengths: %d %d",
372:                                     grid.cells[i].face_id_list.length,
373:                                     grid.cells[i].outsign_list.length);
374:                 throw new FlowSolverException(msg);
375:             }
376:             foreach (j; 0 .. nf) {
377:                 auto my_face = faces[grid.cells[i].face_id_list[j]];
378:                 int my_outsign = grid.cells[i].outsign_list[j];
379:                 c.iface ~= my_face;
380:                 celldata.c2f[i] ~= grid.cells[i].face_id_list[j];
381:                 c.outsign ~= my_outsign;
382:                 celldata.outsigns[i] ~= my_outsign;
383:                 if (my_outsign == 1) {
384:                     if (my_face.left_cell) {
385:                         string msg = format("Already have cell %d attached to left-of-face %d. Attempt to add cell %d.",
386:                                             my_face.left_cell.id, my_face.id, c.id);
387:                         throw new FlowSolverException(msg);
388:                     } else {
389:                         my_face.left_cell = c;
390:                         facedata.f2c[grid.cells[i].face_id_list[j]].left = i;
391:                     }
392:                 } else {
393:                     if (my_face.right_cell) {
394:                         string msg = format("Already have cell %d attached to right-of-face %d. Attempt to add cell %d.",
395:                                             my_face.right_cell.id, my_face.id, c.id);
396:                         throw new FlowSolverException(msg);
397:                     } else {
398:                         my_face.right_cell = c;
399:                         facedata.f2c[grid.cells[i].face_id_list[j]].right = i;
400:                     }
401:                 }
402:             }
403:             celldata.nfaces[i] = celldata.c2f[i].length;
404:             celldata.face_distances[i].length = celldata.nfaces[i];
405:         } // end foreach cells
406:         //
407:         // Set up the lists of indices for look-up of cells and faces
408:         // from a given vertex.
409:         cellIndexListPerVertex.length = vertices.length;
410:         foreach (i, c; cells) {
411:             foreach (vtx; c.vtx) { cellIndexListPerVertex[vtx.id] ~= i; }
412:         }
413:         faceIndexListPerVertex.length = vertices.length;
414:         foreach (i, f; faces) {
415:             foreach (vtx; f.vtx) { faceIndexListPerVertex[vtx.id] ~= i; }

418:         // Work through the faces on the boundaries and add ghost cells.
419:         if (nboundaries != grid.nboundaries) {
420:             string msg = format("Mismatch in number of boundaries: %d %d",
421:                                 nboundaries, grid.nboundaries);
422:             throw new FlowSolverException(msg);
423:         }
424:         int ghost_cell_id = to!int(cells.length);
425:         foreach (i, bndry; grid.boundaries) {
426:             auto nf = bndry.face_id_list.length;
427:             if (nf != bndry.outsign_list.length) {
428:                 string msg = format("Mismatch in face_id_list, outsign_list lengths: %d %d",
429:                                     bndry.face_id_list.length, bndry.outsign_list.length);
430:                 throw new FlowSolverException(msg);
431:             }
432:             foreach (j; 0 .. nf) {
433:                 FVInterface my_face = faces[bndry.face_id_list[j]];
434:                 my_face.is_on_boundary = true;
435:                 my_face.bc_id = i; // note which boundary this face is on
436:                 int my_outsign = bndry.outsign_list[j];
437:                 bc[i].faces ~= my_face;
438:                 bc[i].outsigns ~= my_outsign;
439:                 my_face.i_bndry = bc[i].outsigns.length - 1;
440:                 if (bc[i].ghost_cell_data_available) {
441:                     // We need ghost_cell_id to match the relevant position in the celldata arrays
442:                     FluidFVCell ghost0 = new FluidFVCell(myConfig, &celldata, ghost_cell_id);
443:                     ghost_cell_id++;
444:                     ghost0.contains_flow_data = bc[i].ghost_cell_data_available;
445:                     ghost0.is_ghost = true;
446:                     bc[i].ghostcells ~= ghost0;
447:                     if (my_outsign == 1) {
448:                         if (my_face.right_cell) {
449:                             string msg = format("Already have cell %d attached to right-of-face %d."
450:                                                 ~" Attempt to add ghost cell %d.",
451:                                                 my_face.right_cell.id, my_face.id, ghost0.id);
