1505:     void gather_residual_stencil_lists(int spatial_order_of_jacobian)
1506:     {
1507:         /*
1508:           This function gathers references to the interfaces and cells
1509:           that make up the residual stencil for a cell needed for the
1510:           flow Jacobian construction. These stencils can be thought of
1511:           in terms of what neighbouring cells will have perturbed residuals
1512:           in the event this cells flow state or conserved quantities are
1513:           perturbed.
1514: 
1515:           Note that we need the cells to be in numerical order
1516:           according to their local id for entry into the flow
1517:           Jacobian later
1518: 
1519:           TODO: extend to handle structured grid solver
1520:          */
1521: 
1522:         FluidFVCell[] unordered_cell_list;  // TODO: think about possibly pre-sizing this array
1523:         size_t[size_t] cell_pos_array; // this is used to retrieve a cell from the unordered list
1524: 
1525:         bool include_viscous_effects = myConfig.viscous;
1526:         // when using the flow Jacobian as a precondition matrix for methods such as GMRES it has
1527:         // been observed that only filling entries of the nearest-neighbours provides more
1528:         // robust preconditioning even if viscous effects would suggest a larger stencil is
1529:         // required. Note that we will still apply the viscous effects later when forming
1530:         // the flow Jacobian, we are in effect just dropping some of the Jacobian entries
1531:         // by reducing the stencil footprint.
1532: 
1533:         // add this cell
1534:         size_t[] cell_ids;
1535:         unordered_cell_list ~= cell_cloud[0];
1536:         cell_pos_array[cell_cloud[0].id] = unordered_cell_list.length-1;
1537:         cell_ids ~= cell_cloud[0].id;
1538:         bool nearest_neighbours = false;
1539:         if ( spatial_order_of_jacobian >= 0) { nearest_neighbours = true; }
1540: 
1541:         if (nearest_neighbours) {
1542:             // this first order stencil adds the nearest neighbours
1543:             // Note that if the use_extended_stencil is set to true, then there will be more than just
1544:             // nearest neighbour cells in the cell cloud, so care must be taken to gather the correct cells
1545:             size_t np = iface.length + 1;
1546:             foreach (i; 1 .. np) {
1547:                 FluidFVCell cell = cell_cloud[i];
1548:                 bool cell_exists = cell_ids.canFind(cell.id);
1549:                 if (!cell_exists && !cell.is_ghost && is_interior_to_domain) {
1550:                     unordered_cell_list ~= cell;
1551:                     cell_pos_array[cell.id] = unordered_cell_list.length-1;
1552:                     cell_ids ~= cell.id;
1553:                 }
1554:             } // finished gathering cells
1555: 
1556:         }
1557: 
1558:         bool extended_neighbours = false;
1559:         if ( nearest_neighbours &&
1560:              ( (spatial_order_of_jacobian >= 2) ||
1561:                (spatial_order_of_jacobian >= 1 && include_viscous_effects) ) ) { extended_neighbours = true; }
1562: 
1563:         if (extended_neighbours) {
1564:             // second order (&/or viscous, or first order with viscous effects)
1565:             // stencil adds the nearest neighbours of the nearest neighbours
1566: 
1567:             // gather additional cells
1568:             foreach (icell; 1 .. cell_cloud.length) {
1569:                 foreach (cell; cell_cloud[icell].cell_cloud) {
1570:                     bool cell_exists = cell_ids.canFind(cell.id);
1571:                     if (!cell_exists && !cell.is_ghost && is_interior_to_domain) {
1572:                         unordered_cell_list ~= cell;
1573:                         cell_pos_array[cell.id] = unordered_cell_list.length-1;
1574:                         cell_ids ~= cell.id;
1575:                     }
1576:                 }
1577:             } // finished gathering cells
1578:         }
1579: 
1580:         // now sort the cells
1581:         cell_ids.sort();
1582:         foreach (id; cell_ids) { cell_list ~= unordered_cell_list[cell_pos_array[id]]; }
1583: 
1584:         // gather the interfaces of those cells
1585:         size_t[] face_ids;
1586:         foreach (cell; cell_list) {
1587:             foreach (face; cell.iface) {
1588:                 bool face_exists = face_ids.canFind(face.id);
1589:                 if (!face_exists) {
1590:                     face_list ~= face;
1591:                     face_ids ~= face.id;
1592:                 }
1593:             }
1594:         } // finished gathering faces
1595: 
1596:     } // end gather_residual_stencil_lists()

